       "type": "code",
       "language": "csharp",
       "dir": "ltr",
       "code": "public static Queue<char> What(Queue<char> Q)\n{\n    Queue<char> Q1 = new Queue<char>();\n    Stack<char> S1 = new Stack<char>();\n    Queue<char> Q2 = new Queue<char>();\n    Queue<char> retQ = new Queue<char>();\n    char x;\n    while (!Q.IsEmpty())\n    {\n        x = Q.Remove();\n        Q1.Insert(x);\n        Q2.Insert(x);\n        S1.Push(x);\n    }\n    while (!Q2.IsEmpty())\n        Q.Insert(Q2.Remove());\n    while (!Q1.IsEmpty())\n    {\n        retQ.Insert(Q1.Remove());\n        retQ.Insert(S1.Pop());\n    }\n    return retQ;\n}",
       "origin": "book"
