       "code": "public static bool IsSorted(Queue<int> q)\n{\n    Queue<int> temp = new Queue<int>();\n    bool sorted = true;\n    int prev = q.Head();\n    while (!q.IsEmpty())\n    {\n        int x = q.Remove();\n        if (x < prev)\n            sorted = false;\n        prev = x;\n        temp.Insert(x);\n    }\n    while (!temp.IsEmpty())\n        q.Insert(temp.Remove());\n    return sorted;\n}",
