       "code": "public static Queue<Student> Passed(Queue<Student> q)\n{\n    Queue<Student> temp = new Queue<Student>();\n    Queue<Student> res = new Queue<Student>();\n    while (!q.IsEmpty())\n    {\n        Student s = q.Remove();\n        temp.Insert(s);\n        if (s.GetGrade() >= 55)\n            res.Insert(s);\n    }\n    while (!temp.IsEmpty())\n        q.Insert(temp.Remove());\n    return res;\n}",
